head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gAllChk = false;
scwin.gLdMktTp = js_market;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_1);
        await scwin.setCode();
        txb_msg.setValue("※ 담당자정보의 이메일주소가 없으면 발송되지 않습니다.");
        if (scwin.gLdMktTp === '9') {
            $c.cm.fn_com_isur_all(txb_isur_cd, txb_com_abbrv);
        } else {
            $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30370.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30370.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_Confirm_onclick
 * @description 「확인」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Confirm_onclick = async function() {
    try {
        if (await scwin.confirm() === true) {
            await $c.win.closePopup();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30370.btn_Confirm_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listReceiptPlace();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30370.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_Note_Receiver_OnLoadCompleted
 * @description dts_Note_Receiver 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Note_Receiver_OnLoadCompleted = function(rowcount) {
    try {
        txb_totCnt.setValue("총건수 : " + rowcount);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30370.dts_Note_Receiver_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Note_Receiver_OnLoadError
 * @description dts_Note_Receiver 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Note_Receiver_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Note_Receiver);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30370.dts_Note_Receiver_OnLoadError" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30370.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30370.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30370.txb_isur_cd_onfocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    try {
        if (txb_isur_cd.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30370.txb_isur_cd_onkeyup" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    try {
        if (scwin.gLdMktTp === '9') {
            $c.cm.IsurcdSearch_all(txb_isur_cd, txb_com_abbrv);
        } else if (js_dep_cd.substr(0, 2) === '2B') {
            JongmokSearch(txb_isur_cd, txb_com_abbrv, 'EF', js_market, "A");
        } else {
            $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30370.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30370.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30370.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30370.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30370.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30370.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name btn_SelectedAll_onclick
 * @description 「전체선택」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SelectedAll_onclick = function() {
    try {
        scwin.selectAll();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30370.btn_SelectedAll_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setYear
 * @description 화면 진입 후 연도 조회 중일때 selectbox에 빈칸으로 보여서 '조회중' 이라는 문구를 넣음
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setYear = async function() {
    // 화면 진입 후 연도 조회 중일때 selectbox에 빈칸으로 보여서 '조회중' 이라는 문구를 넣음
    // ^temp 에서 temp는 의미 없는 값이지만, ^뒤에 데이타가 있어야 문구가 노출됨.
    cmb_YearList.CBData = "연도 조회중...^temp";

    // 연도조회(데이타가 등록 되어 있다면 연도가 조회 될 것이고 등록 안되어 있다면 연도가 없음)
    const sbmOptions = {
        id : "sbm_dts_year",
        action : "/EsgSearch.do",
        ref : "",
        target : "dts_year=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listReceiptPlace
 * @description 초기화
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listReceiptPlace = async function() {
    // 초기화
    scwin.gAllChk === false;
    btn_SelectedAll.setValue("전체선택");
    let url = "";
    const year = $c.cp.valueOfIndex(cmb_YearList, "YEAR", cmb_YearList.getSelectedIndex());

    // 이메일 수신자(지배구조공시) 조회
    url += "&inputMessageId=MAIL_RECEIPTPLACE_IN&outputMessageId=MAIL_RECEIPTPLACE_OUT";
    url += "&ISUR_CD=" + txb_isur_cd.getValue();
    url += "&YY=" + year;
    url += "&CHRG_TP_CD=" + cmb_chrg_tp.getValue();
    url += "&SCREN_ID=" + "ULDSTF30370.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Note_Receiver",
        action : "/EmailMgt.do",
        ref : "",
        target : "dts_Note_Receiver=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    await scwin.setYear();
};

/**
 * @method
 * @name confirm
 * @description opener에 값 선택된 값 전달.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.confirm = async function() {
    // opener에 값 선택된 값 전달.

    let total = 0;
    for (let i = 1; i <= dts_Note_Receiver.getRowCount(); i++) {
        let chk = dts_Note_Receiver.getCellData(i, "CHECK");
        /*
        var vCOM_ABBRV = dts_Note_Receiver.NameString(i, "COM_ABBRV");
        var vCORP_USR_NM = dts_Note_Receiver.NameString(i, "CORP_USR_NM");
        var vCELLPHONE_NO = dts_Note_Receiver.NameString(i, "CELLPHONE_NO");
        alert("i=" + i + ", "+ chk + ", " + vCOM_ABBRV + ", vCORP_USR_NM="+vCORP_USR_NM+ ", vCELLPHONE_NO="+vCELLPHONE_NO);
         */
        if (chk === "T" || chk === "1") total++;
    }
    if (total === 0) {
        await $c.win.alert("수신자를 선택하세요.");
        return false;
    }

    // frame.opener.dts_Receiver.ClearData();
    frame.opener.grd_Receiver.setBroadcast(false);
    let j = 1 + frame.opener.dts_Receiver.getRowCount();
    dts_Receiver.setBroadcast(false);
    for (let i = 1; i <= dts_Note_Receiver.getRowCount(); i++) {
        let chk = dts_Note_Receiver.getCellData(i, "CHECK");
        const vLength = dts_Note_Receiver.getCellData(i, "EMAIL").length;
        if (vLength > 0 && (chk === "T" || chk === "1")) {
            frame.opener.dts_Receiver.AddRow();
            frame.opener.dts_Receiver.setCellData(j, "CHECK", "T");
            frame.opener.dts_Receiver.setCellData(j, "COM_ABBRV", dts_Note_Receiver.getCellData(i, "COM_ABBRV"));
            frame.opener.dts_Receiver.setCellData(j, "CHRG_NM", dts_Note_Receiver.getCellData(i, "CHRG_NM"));
            frame.opener.dts_Receiver.setCellData(j, "EMAIL", dts_Note_Receiver.getCellData(i, "EMAIL"));
            frame.opener.dts_Receiver.setCellData(j, "ISUR_CD", dts_Note_Receiver.getCellData(i, "ISUR_CD"));
            j++;
        }
    }
    dts_Receiver.setBroadcast(true, true);
    frame.opener.grd_Receiver.setBroadcast(true);
    return true;
};

/**
 * @method
 * @name selectAll
 * @description select All 처리
 * @returns {void}
 * @hidden N
 */
scwin.selectAll = function() {
    grd_Mail_Receiver.Redraw = false;
    if (scwin.gAllChk === false) {
        // 현재상태가 false이면 전체선택을 클릭릭한것

        scwin.gAllChk = true;
        dts_Note_Receiver.setBroadcast(false);
        for (let i = 0; i < dts_Note_Receiver.getRowCount(); i++) {
            dts_Note_Receiver.setCellData(i + 1, "CHECK", "T");
        }
        dts_Note_Receiver.setBroadcast(true, true);
        btn_SelectedAll.setValue("전체해제");
    } else {
        // 현재상태가  true이면 전체선택을 클릭한것
        scwin.gAllChk = false;
        dts_Note_Receiver.setBroadcast(false);
        for (let i = 0; i < dts_Note_Receiver.getRowCount(); i++) {
            dts_Note_Receiver.setCellData(i + 1, "CHECK", "F");
        }
        dts_Note_Receiver.setBroadcast(true, true);
        btn_SelectedAll.setValue("전체선택");
    }
    grd_Mail_Receiver.Redraw = true;
};
